import {pages as overview} from '../content.mjs';
import {metrics} from '../metrics.mjs';
const h=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const code=s=>`<pre>${h(s)}</pre>`;
const P=(title,body,extra={})=>({title,body,...extra});
const R=id=>{const p=overview.find(x=>x.id===id);if(!p)throw Error(id);return {title:p.title,body:p.body,figure:p.figure,after:p.after,sources:p.sources};};
const road=(goal,files,prereq,steps)=>P('What you will build',`<p>${goal}</p><h3>Before you start</h3><p>${prereq}</p><h3>Files and outputs</h3><p>${files}</p><h3>Build order</h3><ol>${steps.map(s=>`<li>${s}</li>`).join('')}</ol><p class="callout">The checked-in core is an assistant-generated reference. Work on a learning branch. The code excerpts explain selected regions and are not complete replacement modules unless explicitly labeled.</p>`);
const answers=(body)=>P('Answers and completion check',body);
export const books=[
{
 id:'01-foundations',number:1,title:'RTL FOUNDATIONS',subtitle:'Set up the tools and learn to think in clock edges',summary:'Build a working environment, understand binary values and write a self-checking clocked RTL experiment.',sources:['isa','iverilog','verilator','repo'],
 pages:[
 road('You will reproduce the project tools and run a small two-register experiment before editing the CPU. The output is a passing simulation and a written timing prediction.','Dockerfile, Makefile, docs/textbook/series/labs/rtl_basics.sv. Generated files stay in build/learning-series/.','You need a terminal, Git and Docker. No FPGA or RISC-V compiler is required.', ['Create a learning branch and reproduce the reference.','Learn bit widths, signed interpretation and clocked updates.','Run the isolated RTL lab and deliberately change its prediction.','Write the first experiment entry.']),
 R('bits'),R('signed'),R('clock'),R('rtl'),
 P('Step 1: establish a working baseline',`<p>Run these commands from the repository root. Keep the full terminal output in your notes. The image installs Icarus, Verilator, Yosys and nextpnr for later volumes.</p>${code('git switch -c learning/build-core\ndocker build -t rv32-tools .\ndocker run --rm --user "$(id -u):$(id -g)" \\\n  -v "$PWD:/work" rv32-tools make test lint')}<p>A passing run establishes that your environment can execute the reference. It does not establish that a new edit is correct. Commit or preserve the baseline revision before changing the RTL.</p><p>If the branch already exists, use <code>git switch learning/build-core</code>. If Docker cannot connect, solve the installation or daemon problem before changing processor code.</p><p>Write down what the testbench supplies: a clock, reset, separate instruction/data memories and an EBREAK stopping convention. The core itself does not contain those memories.</p>`,{exercise:'1A. Which files would you send to synthesis? Which files exist only to simulate and check behavior?'}),
 P('Step 2: read widths and operators',`<p>In <code>reg [31:0] value</code>, the index range includes 32 bits. In <code>value[7:0]</code>, the slice includes eight bits. A 5-bit register number can name 32 registers.</p>${code("wire [31:0] extended = {{24{byte_value[7]}}, byte_value};\nwire [31:0] logical_shift = value >> amount;\nwire signed [31:0] arithmetic_shift =\n    $signed(value) >>> amount;")}<p>The first expression repeats the sign bit 24 times, then appends the byte. The signed cast in the arithmetic shift matters. Declaring some other signal signed does not make every intermediate expression signed.</p><p>A <code>reg</code> declaration is a Verilog variable kind. Its driving process determines whether synthesis infers storage. Learn the operation and width of every expression before assuming it maps to a specific circuit.</p><p>Check small examples: 0x80 extends to 0xFFFFFF80, and arithmetic shifting −8 by two yields −2. Logical shifting the same 32-bit pattern yields 0x3FFFFFFE.</p>`,{exercise:'1B. Why does a 16-bit signed DOT4 sum fail even though each input lane has only eight bits?'}),
 P('Step 3: run a two-register experiment',`<p>The supplied lab is a complete standalone module and testbench. It uses the same nonblocking edge discipline as the core, without any instruction decoding.</p>${code('docker run --rm --user "$(id -u):$(id -g)" \\\n  -v "$PWD:/work" rv32-tools make learning-labs')}<p>The lab first captures 5 into a while b captures old a=0. At the next edge it captures 9 into a while b captures old a=5. Its assertions check those values.</p><p>Open <code>docs/textbook/series/labs/rtl_basics.sv</code>. Predict the effect of replacing <code>b &lt;= a</code> with a combinational assignment. Explain the change before running a modified experiment.</p><p>Do not use source statement order to invent sequential behavior inside a combinational block. Do not replace every assignment with one operator mechanically. Choose assignments based on the intended hardware and scheduling.</p>`,{exercise:'1C. Before the second active edge, a=5, b=0 and input=9. Give both new register values.'}),
 P('Step 4: write synthesizable next-state logic',`<p>Start a combinational block with defaults for every output it drives. Then override them for selected cases. An output that retains a previous value on an uncovered path can infer a latch.</p>${code("always @* begin\n    result = 0;\n    write_enable = 0;\n    case (operation)\n        2'b00: begin result = a + b; write_enable = 1; end\n        2'b01: begin result = a ^ b; write_enable = 1; end\n        default: begin result = 0; write_enable = 0; end\n    endcase\nend")}<p>This is an isolated pattern, not a new core module. In the actual core, find the defaults for <code>result</code>, <code>wr</code>, <code>ld</code>, <code>st</code>, <code>trap</code> and <code>taken</code>. Follow every override.</p><p>Use <code>make lint</code> after changes. A clean lint result catches many mistakes but does not prove instruction behavior.</p>`),
 P('Debugging the first simulation',`<h3>Unknown values</h3><p>Check whether reset actually reaches a rising edge, whether memory contents are initialized and whether every combinational result is assigned. Inspect the earliest unknown value rather than the final symptom.</p><h3>A value arrives one cycle later</h3><p>Draw old state and scheduled new state at each edge. The extra cycle may be a real register boundary, not simulator lag.</p><h3>The testbench races the core</h3><p>The teaching labs change inputs on falling edges and inspect state after the rising-edge updates settle. Avoid driving and checking the same edge without understanding simulator scheduling.</p><h3>Synthesis rejects testbench code</h3><p>Delay statements, simulation clocks and file-loading behavior belong to testbenches. Synthesize the documented hardware top, not <code>tb</code>.</p><p>Checkpoint: explain the difference between a wire value, a stored register, and a valid instruction. Record one failed prediction and what corrected it.</p>`),
 answers(`<p><b>1A.</b> Synthesize the hardware in <code>rtl/</code> using the chosen top. <code>tests/tb.sv</code>, the Python checker and the standalone teaching bench belong to simulation.</p><p><b>1B.</b> Four products of −128×−128 sum to 65536. Signed 16-bit storage stops at 32767. The full sum needs at least 18 signed bits.</p><p><b>1C.</b> a becomes 9 and b becomes 5. Both right-hand sides use the old state.</p><h3>Ready for Volume 2</h3><p>You can build the tools, run the standalone lab, explain nonblocking assignments and calculate signed extensions. Save your notes before moving into instruction decode.</p>`)
 ]},
{
 id:'02-rv32i-datapath',number:2,title:'THE RV32I DATAPATH',subtitle:'Decode instructions and implement their visible results',summary:'Implement instruction fields, immediates, arithmetic, control flow and byte-addressed memory behavior.',sources:['isa','repo'],
 pages:[road('You will turn instruction words into explicit operations and expected architectural results. Build one instruction family at a time, then compare against the reference.','rtl/rv32_core.sv: instruction fields, imm_* wires, opcode case and memory formatting. tests/run.py: encoders and reference().','Finish Volume 1. Know binary slices, signed interpretation and clocked state.', ['Define the supported execution environment.','Extract fields and reconstruct immediates.','Implement ALU and control-flow cases.','Implement load/store lanes and legality.','Run small instruction-family programs.']),R('isa'),R('encoding'),R('memory'),
 P('Step 1: define the instruction contract',`<p>List each supported operation and its destination, memory effect and next-PC behavior. Keep implementation timing out of this table. ADD writes a sum. SW writes memory. BEQ may select a branch target.</p><p>The reference has integer arithmetic, branches/jumps and ordinary byte/halfword/word memory operations. It omits M, compressed instructions, privileged state and interrupts. Unsupported encodings report a local trap and halt.</p><p>For an initial learning implementation, begin with ADDI, ADD, LW, SW and EBREAK. Mark that smaller subset explicitly. Expand it before claiming the full reference instruction scope.</p><p>Write three examples per family: an ordinary value, a boundary value and a fault or invalid encoding. The standard ISA is the authority for instruction semantics. The local architecture document defines the memory and trap environment.</p>`,{exercise:'2A. Does implementing the ADD opcode alone establish support for every arithmetic operation in RV32I? Explain the missing decode information.'}),
 P('Step 2: extract fields and immediates',`<p>The reference decodes the instruction in EX, after ID/EX has captured it. Use the instruction associated with the current operation, not the live fetch word.</p>${code("wire [6:0] op = x_insn[6:0];\nwire [2:0] funct3 = x_insn[14:12];\nwire [6:0] funct7 = x_insn[31:25];\nwire [31:0] imm_i = {{20{x_insn[31]}},x_insn[31:20]};\nwire [31:0] imm_s = {{20{x_insn[31]}},\n    x_insn[31:25],x_insn[11:7]};")}<p>Store offsets split across two fields. Branch and jump offsets use another arrangement and include an implicit low zero bit. Reconstruct B and J immediates from the ISA diagram, then compare with <code>imm_b</code> and <code>imm_j</code>.</p><p>Use both positive and negative offsets. A forward branch can pass while a backward loop still fails because the sign or high bit is wrong.</p>`,{exercise:'2B. A branch at PC=12 has byte offset −4. What is the target? Why is the offset not added to PC+4?'}),
 P('Build a minimal single-cycle baseline',`<p>The complete source in <code>docs/textbook/series/labs/single_cycle.sv</code> implements ADDI, ADD, aligned LW, aligned SW and EBREAK. It is a teaching subset, not a second measured RV32I core.</p><p>The PC addresses combinational instruction memory. Register reads, decode, ALU and load data settle before the next edge. A legal instruction updates its register or memory effect at that edge. EBREAK or an unsupported instruction halts.</p><p>Start by implementing the PC, reset and register array. Then add opcode/field wires, I/S immediates and ADD/ADDI. Add word-memory ports and alignment checks last. Compare each section with the complete source only after writing your own prediction.</p><p>Run <code>make learning-labs</code> in the tools container. The standalone bench computes 7+3, stores 10 at address 128, loads it into x4 and checks x0, x3, x4 and memory.</p><p class="callout">The teaching top has a different, smaller interface and no retirement trace. Do not substitute it for rv32_core in the pipeline testbench. Volume 3 carries the same conceptual datapath into the real five-stage interface.</p>`,{exercise:'2D. Why does an immediately dependent ADD work without forwarding in this single-cycle subset?'}),
 P('Step 3: implement ALU operations',`<p>Use funct3 to distinguish operation families and funct7 where required. ADD and SUB share opcode/funct3 and differ in funct7. Logical and arithmetic right shifts also need that distinction.</p>${code("// Selected EX behavior, inside the decode block.\nresult = a + b;                  // ADD\nresult = a - b;                  // SUB\nresult = a << b[4:0];            // SLL\nresult = $signed(a) >>> b[4:0];   // SRA\nresult = {31'b0, ($signed(a) < $signed(b))};")}<p>These lines show alternatives, not a block to append unchanged. The last example produces an SLT result. SLTU uses an unsigned comparison. Register shifts use only the low five amount bits in RV32I.</p><p>For immediate operations, choose the sign-extended immediate as the second operand, except for the encoding-specific shift amount. Validate reserved function bits. A permissive decoder can silently execute unsupported instructions.</p><p>Run the learning case <code>decode_add</code>, then add signed/unsigned comparison and extreme-shift examples in a learning branch.</p>`),
 P('Step 4: implement branches and links',`<p>Use the instruction's saved PC for AUIPC, JAL, branch targets and return addresses. JAL/JALR write PC+4 even though the fetch PC may already be ahead.</p>${code("// JALR conceptual EX values.\nresult = x_pc + 4;\ntarget = (a + imm_i) & 32'hfffffffe;\ntaken = 1;\nlegal = (funct3 == 0);")}<p>After clearing bit zero, this 32-bit-instruction-only core still rejects a target whose bit one is set. Check alignment only for taken control targets. An untaken branch must not fault because its unused target would be misaligned.</p><p>Compare signed branch operands for BLT/BGE and unsigned operands for BLTU/BGEU. Use forwarded values once the pipeline overlaps instructions.</p><p>Volume 4 adds the squash and redirect mechanism. Here, the deliverable is correct target and link arithmetic.</p>`),
 P('Step 5: implement memory lanes',`<p>First calculate the effective byte address. Preserve its low bits for lane selection while presenting an aligned word address to memory.</p>${code("assign dmem_addr = {m_result[31:2],2'b0};\nassign dmem_wdata = m_store << (8*m_result[1:0]);\nwire [31:0] shifted_load =\n    dmem_rdata >> (8*m_result[1:0]);")}<p>For a byte store, shift 0001 by the byte offset. For a halfword, shift 0011 after checking halfword alignment. A word uses 1111 after checking word alignment. Gate all strobes with a valid, permitted store.</p><p>LB and LH sign-extend the selected lane. LBU and LHU zero-extend it. LW returns the word. The <code>word_bytes</code> teaching program stores 0x80FF007F and verifies both signed and unsigned reads.</p><p>Do not treat the testbench's address masking as access-fault support. Generated tests stay in range; real out-of-range memory behavior needs an explicit environment contract.</p>`,{exercise:'2C. Which strobe writes one byte at aligned-word offset 2? What word alignment check is required?'}),
 P('Step 6: test legality and side effects',`<p>Default the instruction to a safe behavior, then explicitly select supported cases. The reference computes a legality flag and finally converts illegality or misalignment into a trap.</p>${code("if (!legal || (taken && target[1:0] != 0)) trap = 1;\nif (trap) begin\n    wr = 0; ld = 0; st = 0; taken = 0;\nend")}<p>A faulting instruction must not partially store a word or write a link before halting. Put a younger store after an invalid instruction and check that it never appears in the write stream.</p><p>Run <code>make learning-labs</code> and inspect <code>decode_add</code>, <code>word_bytes</code>, <code>illegal_branch</code> and <code>misaligned_load</code>. These supplement the baseline regression without changing its reported counts.</p><p>If a result differs, decode the instruction word by hand before changing arithmetic. A wrong register field or immediate often looks like a broken ALU.</p>`),
 answers(`<p><b>2A.</b> No. funct3 and funct7 refine the operation, and opcode 0x13 covers immediate arithmetic separately. Legality checks are part of decode.</p><p><b>2B.</b> Target=8. RISC-V branch offsets are relative to the branch instruction's PC.</p><p><b>2C.</b> The byte strobe is 0100. A word access requires effective_address[1:0]=0; halfwords require bit zero=0.</p><p><b>2D.</b> Each earlier instruction finishes its state update at the preceding edge. The next instruction reads the updated register file during its own full cycle.</p><h3>Completion check</h3><p>Decode one R instruction and each immediate format by hand. Demonstrate signed/unsigned loads, a backward branch, a jump link and a rejected encoding. Then add pipeline timing in Volume 3.</p>`)
 ]},
{
 id:'03-pipeline',number:3,title:'BUILD THE PIPELINE',subtitle:'Divide instruction work into five valid stages',summary:'Plan stage boundaries, carry control with data, implement edge updates and inspect a correct pipeline trace.',sources:['brown','repo','isa'],
 pages:[road('You will design the stage register contents and explain how independent instructions overlap before introducing dependency handling.','rtl/rv32_core.sv: pc, f_*, x_*, m_*, w_* and rising-edge block. tests/tb.sv: retirement output.','Complete instruction result calculations from Volume 2. Preserve a reference revision.', ['Specify the work and outputs of each stage.','List every field crossing each boundary.','Implement reset and unconditional older-stage advance.','Issue spaced independent programs.','Add retirement records and draw a cycle table.']),R('single'),R('pipeline'),
 P('Step 1: assign work to stages',`<p>IF presents PC to instruction memory. ID reads registers and captures the instruction's context. EX performs the ALU operation, target decision or address calculation. MEM performs the data-port transaction. WB updates the register file and reports completion.</p><p>Draw five columns and place every signal-producing operation in one column. Mark the clock boundary between columns. Keep the assumed combinational memory read visible; moving to synchronous RAM changes this allocation.</p><p>The reference names stage storage by prefixes: f is IF/ID, x is ID/EX, m is EX/MEM and w is MEM/WB. There is no extra “f stage” beyond the five logical stages.</p><p>For an ADD, MEM still carries its result onward even though no data read occurs. For a store, WB produces a trace record even though no register destination exists.</p><p class="callout">Keep instruction identity attached to its work. Saved PC and instruction bits make debugging possible and prevent using the speculative fetch PC for older instructions.</p>`),
 P('Step 2: list each pipeline payload',`<p>Write the boundary contents before coding. Start with ADD, then extend the list for loads, stores and control flow.</p><dl class="glossary"><dt>IF/ID</dt><dd>Valid bit, fetched PC and instruction word.</dd><dt>ID/EX</dt><dd>Valid bit, PC, instruction and the two captured register values.</dd><dt>EX/MEM</dt><dd>Valid bit, PC, instruction, result/address, store data, destination, write/load/store controls, trap and funct3.</dd><dt>MEM/WB</dt><dd>Valid bit, PC, instruction, final result, destination, write control and trap.</dd></dl><p>The reference keeps instruction bits through EX rather than storing a fully expanded decoded control bundle in ID/EX. That is one legitimate organization, not a universal requirement.</p><p>Trace a store's source value separately from its address. Trace a load's size/signedness until MEM. Trace a jump's link until WB.</p>`,{exercise:'3A. Which boundary must retain a load’s funct3, and why can it not disappear after EX?'}),
 P('Step 3: implement the older-stage updates',`<p>Start with the steady flow at the back of the pipeline. These updates occur on every ordinary non-reset edge, including a front-end stall.</p>${code("w_valid <= m_valid;\nw_pc <= m_pc; w_insn <= m_insn; w_rd <= m_rd;\nw_write <= m_write; w_trap <= m_trap;\nw_result <= m_load ? load_value : m_result;\nm_valid <= x_valid;\nm_pc <= x_pc; m_insn <= x_insn;\nm_result <= result; m_store <= b;")}<p>This excerpt omits other EX/MEM fields for space. Read and implement the complete destination/control assignments in the actual source. All right-hand sides refer to pre-edge values.</p><p>If a load stalls the younger consumer, freezing these older stages too would stop the producer from reaching WB. A front-end stall must create space while allowing the required value to advance.</p><p>For the first dependency-free experiment, omit special stall behavior only in an explicitly labeled learning version and use NOP spacing. The finished core must implement Volume 4 before ordinary dependent programs are correct.</p>`),
 P('Step 4: implement valid bits and reset',`<p>A valid bit is the authority for side effects. An invalid stage may still contain stale register numbers or instruction bits. Do not interpret those bits as a live operation.</p>${code("if (reset) begin\n    pc <= 0;\n    f_valid <= 0; x_valid <= 0;\n    m_valid <= 0; w_valid <= 0;\nend")}<p>The reference also initializes stored data/control fields and clears the register file. Reset is synchronous and active high. External memories are not reset through the core.</p><p>Every memory write must require a valid MEM instruction. Every register write must require a valid, non-trapping WB writer and rd≠0. Keep the x0 rule even if a test never writes x0.</p><p>To insert a bubble, clear the destination valid bit. Encoding an ADDI x0,x0,0 is not the same representation: it remains a real valid instruction and can alter retirement counts.</p>`,{exercise:'3B. Why is x_insn=0 not a safe way to represent a bubble in this core?'}),
 P('Step 5: capture the front end',`<p>When nothing holds or redirects the front end, transfer the decoded instruction context into ID/EX, capture the new fetch in IF/ID and advance PC by four.</p>${code("x_valid <= f_valid; x_pc <= f_pc; x_insn <= f_insn;\nf_valid <= !halted; f_pc <= pc; f_insn <= imem_rdata;\nif (!halted) pc <= pc + 4;")}<p>The complete ID operand capture needs the WB-to-ID bypass explained in Volume 4. A plain read from regs can be stale at a coincident WB edge.</p><p>Temporarily spaced programs help isolate stage-transfer errors. Use <code>pipeline_spaced</code> in the teaching labs. Check PC sequence and instruction identity, not just the final sum.</p><p>If PC values jump or repeat without an intended redirect, inspect whether a stage saved the old PC or incorrectly read the current fetch PC. Nonblocking assignments make the old/new distinction precise.</p>`),
 P('Step 6: create an observable retirement record',`<p>The local interface reports one completed WB-stage instruction at a time. It carries valid, PC, instruction, destination, value and trap, plus an interrupt flag that only the ZICSR=1 build sets. riscv-formal reads a separate RVFI trace.</p>${code("retire_valid <= w_valid;\nretire_pc <= w_pc; retire_insn <= w_insn;\nretire_trap <= w_valid && w_trap;\nif (w_valid && w_write && !w_trap && w_rd != 0)\n    regs[w_rd] <= w_result;")}<p>For nonwriters, report no architectural register destination/value. For x0, report no retained result. Keep trap records distinguishable from ordinary completion.</p><p>The testbench prints STORE events when memory changes and RET records after the WB update has settled. Store memory effects occur in MEM, before their local WB notification.</p><p>Run a three-instruction independent program, write its IF/ID/EX/MEM/WB table, and compare it with the saved PCs in the printed trace. Do not infer stage timing only from text-output order.</p>`),
 P('Step 7: check fill, drain and lost instructions',`<p>For N independent instructions entering an empty five-stage pipeline and draining normally, the ideal stage-interval count is N+4. Testbench reset and halt bookkeeping can use a different counting window, so state your convention.</p><p>Count each input instruction once in the retirement stream. Check that no initial garbage instruction retires after reset. Check that the last ordinary instruction is not lost when EBREAK follows it.</p><p>Test a sequence with unique PCs and unique results. Repeated NOPs are useful spacing but poor identifiers for diagnosing a duplicate or missing instruction.</p><p>Run <code>make test lint</code> after implementing the complete pipeline and hazard handling. Keep the intermediate spaced result as a teaching artifact, not the final correctness claim.</p><h3>Debugging order</h3><p>Find the first incorrect boundary, check its valid bit, then compare its saved instruction/PC/control with the previous stage. Repair the earliest divergence rather than compensating downstream.</p>`),
 answers(`<p><b>3A.</b> EX/MEM must preserve the size/signedness field until MEM formats the loaded word. An address alone cannot distinguish LB from LBU or LW.</p><p><b>3B.</b> The zero instruction word is unsupported and traps if treated as valid. A bubble is a false valid bit, independent of stale instruction contents.</p><h3>Completion check</h3><p>You can list all boundary payloads, explain old/new edge state, trace fill/drain and show one retirement per valid instruction. Move to hazards before running dependent code without spacing.</p>`)
 ]},
{
 id:'04-hazards',number:4,title:'HAZARDS AND CONTROL',subtitle:'Forward available values, wait for loads and discard wrong paths',summary:'Implement operand forwarding, WB-to-ID bypass, load interlocks, redirects and halt/drain behavior.',sources:['brown','isa','repo'],
 pages:[road('You will preserve architectural results when instructions depend on unfinished work or change the control path.','rtl/rv32_core.sv: operand block, uses_rs*, hazard, redirect/fault and front-end edge cases. Teaching cases: forward_priority, wb_id, load_store, load_branch, load_jalr and branch_flush.','Complete the stage transfers from Volume 3. Know when each result becomes available.', ['Build producer/consumer timing tables.','Implement newest-result forwarding for both sources.','Add same-edge WB bypass.','Add one-cycle load interlock.','Implement EX redirect and trap drain.','Check false dependencies and wrong-path side effects.']),R('forwarding'),R('wbid'),R('load'),
 P('Step 1: wire both operand muxes',`<p>Use ID/EX values as defaults. Override them with matching valid WB results. Finally override with a matching non-load MEM result, which represents the newer producer.</p>${code("a = x_a; b = x_b;\nif (w_valid && w_write && w_rd != 0) begin\n    if (rs1 == w_rd) a = w_result;\n    if (rs2 == w_rd) b = w_result;\nend\nif (m_valid && m_write && !m_load && !m_trap && m_rd != 0) begin\n    if (rs1 == m_rd) a = m_result;\n    if (rs2 == m_rd) b = m_result;\nend")}<p>This is the reference's combinational ordering. Ensure trap handling suppresses writes. Loads are excluded from the MEM bypass because their m_result contains the address.</p><p>Feed a and b into branch comparisons, store-data selection, JALR and DOT4 as well as ALU arithmetic. Testing only an ADD chain leaves those consumers unproven.</p>`,{exercise:'4A. Two consecutive instructions write x1=5 and x1=8. What value must a following ADD use?'}),
 P('Step 2: handle the WB/ID coincidence',`<p>When an ID instruction captures operands on the same edge that WB writes the register file, an ordinary array read can still see old contents. Explicitly select the old w_result for a matching source.</p>${code("x_a <= f_insn[19:15] == 0 ? 32'b0 :\n    (w_valid && w_write && !w_trap &&\n     w_rd == f_insn[19:15] ? w_result : regs[f_insn[19:15]]);")}<p>Mirror the expression for rs2. The source register here comes from f_insn, because the consumer is in ID. The EX bypass comparisons instead use the instruction already in x_insn.</p><p>Use the <code>wb_id</code> case: producer, two unrelated instructions, then consumer. Adjacent dependencies alone do not isolate this boundary.</p><p>If you deliberately remove this bypass, predict which operand the consumer captures. In a temporary experiment, verify the first failing result and restore the good design.</p>`),
 P('Step 3: identify a true load consumer',`<p>The producer is the valid load in EX. The consumer is the valid instruction in ID. Check a nonzero load destination against each source that the consumer actually uses.</p>${code("wire hazard = f_valid && x_valid && ld && !trap &&\n    x_insn[11:7] != 0 &&\n    ((uses_rs1 && f_insn[19:15] == x_insn[11:7]) ||\n     (uses_rs2 && f_insn[24:20] == x_insn[11:7]));")}<p>Construct uses_rs1 and uses_rs2 from the consumer's opcode. ADDI uses rs1 and an immediate. Its bits 24:20 are not an rs2 dependency. Stores use both a base and data source. DOT4 uses both sources.</p><p>For <code>lw x0,...</code>, no consumer needs its discarded result. A false stall is a performance defect even when the final values are correct.</p>`,{exercise:'4B. Why can comparing every instruction’s bits 24:20 create a false hazard?'}),
 P('Step 4: insert one bubble without stopping the load',`<p>At the interlock edge, hold PC and IF/ID. Clear x_valid so EX receives a bubble. Continue the previously described EX/MEM and MEM/WB updates.</p>${code("if (redirect || fault) begin\n    f_valid <= 0; x_valid <= 0;\n    if (redirect) pc <= target;\n    if (fault) halted <= 1;\nend else if (hazard) begin\n    x_valid <= 0;\nend else begin\n    // Ordinary ID/EX and IF/ID capture, then PC advance.\nend")}<p>Leaving a register unassigned in this clocked branch holds its old value. That is intended storage, unlike an omitted assignment in a combinational block.</p><p>The older producer advances independently. In the next interval, the load reaches WB and the consumer can enter EX with a forwarded result.</p><p>A redirect/fault outranks the younger dependency. Do not freeze a wrong-path instruction merely because it happens to look dependent.</p>`,{figure:'timeline'}),
 R('control'),
 P('Step 5: squash effects, then drain traps',`<p>EX decides a redirect. At its edge, clear the younger f_valid and x_valid entries. The target becomes the IF address in the next interval. Do not capture the old wrong-path instruction response as target work.</p><p>A trap similarly invalidates younger work and sets halted. Older instructions continue toward WB. The faulting instruction carries a trap record while its register/memory controls are disabled.</p><p>Use <code>branch_flush</code> to check a skipped store, <code>load_branch</code> to exercise a loaded comparison operand, and <code>load_jalr</code> to exercise a loaded target base.</p><p>Observe memory writes separately. Correct final register values can coexist with an incorrect transient store. Place distinctive data at the wrong-path destination and verify that no write event occurs there.</p><p class="callout">The physical memory side effect occurs in MEM. Valid bits and squash timing must prevent wrong-path stores from reaching that stage as valid stores.</p>`),
 P('Step 6: make a hazard test matrix',`<p>Cross producer type with consumer use, source position and separation. At minimum, test ALU and load producers feeding ALU, store address, store data, branch, JALR and DOT4.</p><p>Also test competing writers, x0, a dependency on both sources, a same-edge WB/ID case and nonconsumer immediate bits. Verify exact stall behavior with a dedicated timing check when the claim concerns performance.</p><p>The learning runner prints stall and flush event counts for each small program. These events are sampled by the current testbench on falling edges. Align the definition before treating them as a general CPI measurement.</p><p>To debug, find the consumer's EX cycle, identify the selected source, then ask where the newest producer resides. If that source does not yet exist, inspect the interlock. If the consumer is wrong-path work, inspect flush validity instead.</p>`,{exercise:'4C. If a load-to-store program stores the load address, which rule was probably violated?'}),
 answers(`<p><b>4A.</b> Use 8. The newer matching MEM producer must override the older WB producer.</p><p><b>4B.</b> Immediate bits can resemble a register index without naming a register source. Decode actual source use before comparing.</p><p><b>4C.</b> A load address was probably forwarded as data, or the load-use bubble was missing. MEM-load producers must not use the non-load result bypass.</p><h3>Completion check</h3><p>All named teaching hazards pass, no wrong-path store appears, and you can draw the load/add/store and EX branch timelines. The reference's generated hazard cross (<code>tests/hazards.py</code>) is the next step up.</p>`)
 ]},
{
 id:'05-dot4',number:5,title:'BUILD DOT4',subtitle:'Specify, encode and test a signed packed instruction',summary:'Implement a custom four-lane signed dot product and design a fair software/hardware comparison.',sources:['isa','gnu','repo'],
 pages:[road('You will write an exact custom-instruction contract, implement signed arithmetic in EX, encode it in tests and evaluate its limits.','rtl/rv32_core.sv: signed dot loop and opcode 0x0b case. tests/run.py: r(), signed(), reference() and DOT4 cases.','Understand operand forwarding and load interlocks. Know two’s-complement bytes.', ['Freeze lane semantics and result width.','Choose one exact custom encoding.','Implement signed products and a wide sum.','Extend the reference and directed tests.','Exercise dependencies and invalid encodings.','Plan a matched scalar comparison.']),R('dot'),R('dotworked'),
 P('Step 1: freeze the arithmetic contract',`<p>Write the operation before writing RTL. Lane i is bits 8i+7 through 8i of each source. Interpret each lane as signed independently, multiply corresponding values, and sum four products.</p><p>Choose explicitly whether the instruction accumulates old rd, saturates or rounds. This instruction does none of those. Its only input registers are rs1 and rs2; rd receives a signed 32-bit result.</p><p>The most positive product is −128×−128=16384. The most negative is −128×127=−16256. Four products therefore span −65024 through 65536. Select an intermediate width that can hold both extremes.</p><p>Write independent hand cases for all-zero lanes, one active lane, mixed signs, the maximum and the minimum. Keep a lane-order example with distinct bytes to reveal a swapped lane mapping.</p>`,{exercise:'5A. What goes wrong if all four products are added into a signed 16-bit accumulator?'}),
 P('Step 2: allocate an exact encoding',`<p>Use the custom-0 major opcode reserved for project extensions. This implementation selects opcode 0x0b, funct3=0 and funct7=0, with normal R-format register fields.</p>${code("// Inside the EX opcode case.\n7'h0b: begin\n    wr = 1;\n    result = dot;\n    legal = (funct3 == 0 && funct7 == 0);\nend")}<p>Reject other custom-0 function combinations. Reserved custom space does not mean every possible function field is this instruction.</p><p>The local encoder is <code>r(0, rd, rs1, rs2, op=0x0b)</code>. Standard GNU assembly can emit the same R-format fields with <code>.insn r 0x0b, 0, 0, a0, a1, a2</code>. The directive emits bytes; it does not teach a stock simulator or compiler the operation's meaning.</p><p>No compiler backend change is needed for this first prototype. A custom mnemonic and scheduling support are separate later projects.</p>`),
 P('Step 3: preserve signedness and width in RTL',`<p>The loop operates on the already forwarded EX inputs a and b. Start the sum at zero in the combinational block.</p>${code("reg signed [31:0] dot;\ninteger lane;\n// Inside the combinational EX block.\ndot = 0;\nfor (lane = 0; lane < 4; lane = lane + 1)\n    dot = dot + ($signed(a[lane*8 +: 8]) *\n                 $signed(b[lane*8 +: 8]));")}<p>The indexed part-select has a constant width of eight. The casts interpret each selected byte as signed. Keep the destination wide enough and verify how the simulator sizes the expression.</p><p>Test extrema and mixed signs immediately. An unsigned multiplication error can pass positive-only tests. A narrow sum can pass most random small inputs.</p><p>Synthesis will unroll the constant four-iteration loop into hardware. It does not imply four execution cycles. Here the combinational unit shares one EX interval.</p>`),
 P('Step 4: write a separate scalar oracle',`<p>The reference must unpack bytes and interpret them explicitly. Python's integer type does not automatically have signed 8-bit lane behavior.</p>${code("def signed8(n):\n    n &= 255\n    return n - 256 if n & 128 else n\n\ndef dot4(a, b):\n    return sum(signed8(a >> (8*i)) *\n               signed8(b >> (8*i)) for i in range(4))")}<p>Check <code>dot4(0x0102ff80, 0x020304ff)==132</code>. Check the positive extreme 65536 and negative extreme −65024. Mask the architectural output to 32 bits when comparing RTL register values.</p><p>The local model already handles custom opcode 0x0b. When implementing your own version, update the checker from the written contract rather than translating the RTL line by line.</p><p>Run <code>dot_mixed</code> and <code>dot_extremes</code> in the teaching labs. An exhaustive isolated-lane operand sweep is additional work, not part of the reference claim.</p>`),
 P('Step 5: exercise real pipeline consumers',`<p>A correct combinational dot function can still fail as an instruction. Use an ALU producer feeding each source, a load feeding either source, DOT4 feeding another DOT4, and DOT4 feeding a store or branch.</p><p>The <code>dot_load</code> teaching case loads packed bytes and immediately uses them in DOT4. It should receive the same load interlock as ordinary two-source arithmetic. The subsequent store must receive the dot result through normal forwarding.</p><p>Try rd=x0 and invalid funct3/funct7. x0 must remain zero, and the invalid instruction must trap without a younger memory side effect.</p><p>Inspect <code>uses_rs1</code> and <code>uses_rs2</code>. Both must recognize the custom opcode. A decoder change without the matching hazard-source update creates a subtle load-use bug.</p>`,{exercise:'5B. Why is adding only a new ALU case insufficient to integrate DOT4 safely?'}),
 P('Step 6: evaluate a fair comparison',`<p>Define identical input arrays, signed semantics and checked outputs for a scalar kernel and a DOT4 kernel. Count useful dot-product outputs, not only retired instructions.</p><p>Base RV32I has no MUL. The scalar baseline needs a documented software multiplication routine. An RV32IM binary changes the baseline. Include loads, packing and loop overhead if they belong to the intended workload.</p><p>Measure total cycles for both implementations. Route both configurations with the same shell, target, constraints, tools and seeds. Then use each configuration's own timing estimate to convert cycles to estimated execution time.</p><p><code>make bench ablation</code> does this for the reference: ${metrics.speedup.vsQsquare}× over the strongest RV32I baseline at N=${metrics.speedup.n}, clock cost included. Instruction-count reduction alone does not prove application speedup. Timing and LUTs alone do not measure energy.</p><p>Checkpoint: state a falsifiable hypothesis, such as “DOT4 reduces total cycles on a fixed packed kernel, but may increase the critical path.” Record the evidence before reaching a conclusion.</p>`),
 answers(`<p><b>5A.</b> The maximum sum 65536 exceeds signed 16-bit range. The accumulator wraps and produces a wrong architectural result.</p><p><b>5B.</b> Encoding, legality, reference semantics, both source-use predicates and hazard consumers must agree. Otherwise a load can feed stale DOT4 operands even when the arithmetic unit itself is correct.</p><h3>Completion check</h3><p>Explain the exact encoding and lane math. Pass signed extrema, mixed lanes, dependencies and invalid encodings. Keep workload and physical-performance claims pending until their separate experiments run.</p>`)
 ]},
{
 id:'06-verification',number:6,title:'VERIFY THE CORE',subtitle:'Build an oracle, design tests and interpret coverage',summary:'Run differential tests, verify memory writes, add directed cases, preserve seeds and measure a named coverage metric.',sources:['verilator','iverilog','act4','formal','repo'],
 pages:[road('You will build evidence that each supported instruction produces the intended outcome under the stated memory contract. Distinguish a test pass from coverage and certification.','tests/run.py, tests/tb.sv, tests/coverage_main.cpp, scripts/coverage.py and reports/. Teaching labs write only build/learning-series/.','Understand the instruction contract and hazards. Know how to read a trace.', ['Write architectural predictions independent of stage timing.','Drive program words into the RTL.','Compare ordered retirements and byte writes.','Add directed cases and seeded random programs.','Collect and explain core-only coverage.','Plan stronger external checks.']),R('oracle'),R('tests'),R('coverage'),
 P('Step 1: define the oracle state',`<p>The model needs 32 integer registers, byte-addressed data memory, PC and a stopping rule. It executes sequentially. It must not model forwarding or pipeline bubbles to predict architectural results.</p>${code("regs = [0] * 32\nmemory = bytearray(16384)\npc = 0\n# Per instruction:\n# decode -> compute result and next PC -> apply permitted effects\n# mask register results to 32 bits, then keep x0 equal to zero")}<p>Use explicit signed conversion for signed comparisons, immediate interpretation and byte lanes. Apply 32-bit masking at architectural boundaries. Derive operations from the written contract, not simulator output.</p><p>For each instruction, record PC, word, retained destination/value and trap. For stores, record each written byte and address. Distinguish ordinary completion from a local halt/trap notification.</p><p>Start with hand-calculated programs before random generation. Two implementations can agree on the same wrong interpretation.</p>`),
 P('Step 2: drive the actual RTL',`<p>The supplied testbench loads a hex word file into instruction memory and supplies a byte-addressed data array. Each line contains one eight-digit hexadecimal instruction, without an address prefix.</p>${code('iverilog -g2012 -s tb -o build/sim \\\n  rtl/rv32_core.sv tests/tb.sv\nvvp build/sim +program=build/forwarding.hex')}<p>These native-tool commands run inside the tools container. Run <code>make test</code> first to create the program and executable, or create your own hex file explicitly.</p><p>The bench samples memory-write strobes on rising edges and prints retirement after updates settle. It stops on a trap record and has a bounded timeout. EBREAK is the ordinary test-end instruction in these programs.</p><p>Keep generated accesses within the memory range. The bench masks addresses; that convenience is not a hardware protection or access-fault feature.</p>`),
 P('Step 3: compare the first divergence',`<p>Parse each RET record into a fixed tuple. Compare complete lists, including lengths. A design that produces a correct prefix then silently loses instructions must fail.</p>${code("observed = [pc, insn, rd, value, trap, intr]\nexpected = reference_instruction_record\nassert observed == expected\n# Also compare the complete ordered byte-write list.")}<p>This is explanatory pseudocode. The executable implementation is in <code>tests/run.py</code> and the teaching runner. A source-path mismatch or stale executable can otherwise make a test appear to check the wrong RTL revision.</p><p>When a test fails, identify the first differing PC and word. Decode it by hand, then inspect preceding producers and redirections. Store mismatches require a separate look at address, byte lane and forwarded data.</p><p>Save the failure input and seed before editing anything. Reduce it to the shortest reproducing program when possible.</p>`,{exercise:'6A. Why can a final memory signature miss a wrong-path store that an ordered write-stream comparison catches?'}),
 P('Step 4: add a named directed case',`<p>Use the supplied instruction encoders to construct a small, auditable program. This example is a teaching case, not an automatic addition to the baseline suite.</p>${code("yield 'my_load_store', [\n    imm(0, 1, 0, 9),\n    store(2, 0, 1, 128),\n    imm(2, 2, 0, 128, 3),\n    store(2, 0, 2, 132),\n    0x00100073,\n]")}<p>Predict x2=9 and word 132=9. Explain why the load-to-store pair needs the interlock. Include x0, invalid encodings, backward control flow and both operand positions in later cases.</p><p>Add a case inside <code>suite()</code> on your learning branch. The normal runner's functional-bin assertion expects its complete suite, so a tiny standalone subset should use the separate learning runner instead of deleting all other cases.</p>`),
 P('Step 5: use randomness reproducibly',`<p>A seed identifies a repeatable random sequence. Preserve the generator source revision along with the seed: changing generation code can change the program even with the same number.</p><p>Constrain addresses and legal encodings for ordinary random programs. Test illegal instructions separately, because the first expected trap ends execution and prevents later random instructions from exercising anything.</p><p>Use multiple register dependencies and mixed loads/stores. Keep a known reachable stopping instruction. A random jump generator needs control-flow constraints to avoid endless loops or out-of-range targets.</p><p>The reference suite uses ${metrics.regression.seeds} deterministic seeds, directed cases and ${metrics.regression.hazardPrograms} generated hazard programs. This is finite evidence, not exhaustive state-space exploration. Report program counts, retired records and the scope of the generator.</p><p>When a random failure appears, save its exact hex words. A failing program is more useful than a seed that no longer reproduces after a generator edit.</p>`),
 P('Step 6: collect coverage with a declared scope',`<p>Run the existing coverage target with the tools container. It builds the Verilator testbench, runs the suite, merges per-program data and counts core line instrumentation points.</p>${code('docker run --rm --user "$(id -u):$(id -g)" \\\n  -v "$PWD:/work" rv32-tools make coverage')}<p>Read <code>reports/line-coverage.json</code>: metric, hit, total, percent, scope, uncovered points, tool and RTL hash. Inspect the raw merged data if the parser finds no points after a tool update.</p><p>Add an invalid branch-funct3 case to exercise the current unhit default. Verify its trap and suppressed younger store, not just an increased percentage. A different source revision may have a different denominator.</p><p>Keep the ${metrics.regression.binsTotal}-bin functional plan separate from RTL line coverage. The reference added its hazard cross as a separate, documented plan. Do not erase hard bins to improve a headline.</p>`,{exercise:`6B. If a new simulator instruments more points, should you keep quoting the old ${metrics.coverage.percent}%?`}),
 P('Step 7: strengthen the evidence',`<p>Add invariants for x0, valid-controlled side effects, stable front-end state during a stall and younger squash on a redirect. Prove that a deliberate defect can trigger each assertion before relying on it.</p><p>Test reset while instructions are in flight. Decide how external memory treats reset and prevent unintended writes during that transition. Initial reset tests alone do not establish mid-flight reset correctness.</p><p>For external ISA checks, compare against another model. The reference matches Spike on ${metrics.spike.archPassed}/${metrics.spike.archTotal} riscv-arch-test ${metrics.spike.archRelease} RV32I tests; that older suite is not ACT4. For formal work, implement a complete RVFI adapter and state the properties checked.</p><p>The project has no formal integration. A partial retirement trace is not a completed formal interface, and local code coverage is not architectural certification.</p><p>Checkpoint: preserve one failure-to-fix example, a full passing regression, and a coverage report whose denominator you can explain.</p>`),
 answers(`<p><b>6A.</b> A later store can overwrite the wrong-path corruption before the final signature is checked. The ordered write list still records the forbidden event.</p><p><b>6B.</b> No. Recompute and report the new numerator, denominator, version and source hash. Explain why the metric changed.</p><h3>Completion check</h3><p>Reproduce a passing suite in both simulators, diagnose a deliberate mismatch, preserve seeds/words and explain the limits of every percentage. Never relabel finite simulation as proof or certification.</p>`)
 ]},
{
 id:'07-synthesis-fpga',number:7,title:'SYNTHESIS AND FPGA',subtitle:'Map the core, read timing and plan real board integration',summary:'Run open-source implementation, interpret resources and critical paths, and design a synchronous-memory board adaptation.',sources:['yosys','nextpnr','repo','isa'],
 pages:[road('You will map and route the measurement shell, interpret raw reports and understand what remains before a real FPGA demonstration.','Makefile, rtl/timing_top.sv, scripts/metrics.py, build/synthesis.log, build/nextpnr.log and reports/implementation.json.','A passing functional regression from Volume 6. Know register-to-register timing.', ['Choose the exact top and implementation boundary.','Run synthesis and route with recorded tools and constraints.','Read packed resources and the critical path.','Perform a controlled implementation comparison.','Plan clock/reset, synchronous memory and observable board results.']),R('synthesis'),R('performance'),
 P('Step 1: define what is being measured',`<p><code>make synth</code> maps rv32_core alone. <code>make timing</code> maps timing_top, which adds registered external inputs and an observable output register. These are different tops with different resource costs.</p><p>The shell makes instruction/load inputs synchronous endpoints and keeps core outputs observable so optimization cannot discard the datapath. It does not execute a stored program.</p><p>Write the boundary explicitly: no instruction/data memories, UART, programmer, boot path or board constraints are included. A folded observation signal preserves hardware observability for implementation; it is not a correctness signature from a running application.</p><p>Choose HX8K CT256, the 12 MHz constraint and seed 1 to reproduce the reference. Record the exact tool versions and RTL hashes. Other devices or versions are separate experiments.</p>`,{exercise:'7A. Why is comparing the LUT count from make synth to the count from make timing not a controlled DOT4-area experiment?'}),
 P('Step 2: run mapping and route',`<p>Use the supplied target rather than manually skipping its reporting stage.</p>${code('docker run --rm --user "$(id -u):$(id -g)" \\\n  -v "$PWD:/work" rv32-tools make timing')}<p>Yosys reads both SystemVerilog hardware files and runs synth_ice40 for timing_top. nextpnr consumes the JSON netlist, chooses physical resources and routes the connections.</p><p>The command sets HX8K, package CT256, seed 1 and a 12 MHz constraint. Package I/O is allowed to remain unconstrained. The flow saves an ASC implementation file and a JSON timing report under build/.</p><p>Check the command exit status and the full log. A generated netlist alone is not a completed route. A route completing at a lower requested target does not establish timing at a previously quoted higher target.</p><p>The measurement parser archives the raw route report/log and a compressed synthesis log in reports/raw/.</p>`),
 P('Step 3: read resource counts correctly',`<p>Read synthesis primitive counts and packed place-and-route use as related but different views. A LUT, flip-flop and packed logic cell are not interchangeable units.</p><p>The reference shell maps to ${metrics.area.lut4} LUT4 primitives and ${metrics.area.flipFlops} flip-flops, packed into ${metrics.area.logicCells} of ${metrics.area.logicCellsAvailable} HX8K logic cells. Its memories are external to the boundary, so zero block RAM use does not mean a complete system needs no memory.</p><p>HX8K lacks hard DSP blocks. The dot-product multiplication therefore uses logic. Resource use on a different family with DSPs can differ substantially.</p><p>Do not convert FPGA cell counts into square millimeters or energy without an appropriate physical model. Large resettable register arrays can also affect inference and mapping.</p><p>Open the JSON report and identify the keys for synthesis primitives, packed utilization, flip-flops, target and source hashes. Explain which count you would use in a README and why.</p>`),
 P('Step 4: trace the limiting timing path',`<p>Find the clock's achieved and constrained values in the route report. Then read the detailed slow path in the log: launch register, combinational cells/wires and destination register.</p><p>Classify the path before optimizing. It may involve the dot unit, a forwarding mux, address calculation, decode or register-file selection. Do not assume the largest-looking arithmetic block is the bottleneck.</p><p>Over route seeds ${metrics.fmax.seeds} the reference's estimated internal Fmax has a median of ${metrics.fmax.median} MHz (${metrics.fmax.min}–${metrics.fmax.max}) against a requested ${metrics.fmax.constraint} MHz constraint. Each estimate belongs to one placement. The design was not board-tested at any of them.</p><p>Input/output timing is not signed off. The synchronous shell provides internal endpoints, but unconstrained package pins prevent a complete board-interface claim.</p><p>Propose one change that shortens the identified path, then rerun both functional regression and implementation. A timing improvement with incorrect execution is not a useful result.</p>`,{exercise:'7B. Can a successful Yosys-only run justify “running at 50 MHz”?'}),
 P('Step 5: compare configurations fairly',`<p>Create an experiment branch or separate worktree. Compare a DOT4-enabled configuration against one that rejects DOT4, keeping top, memory boundary, device, tools, constraints and route seeds identical.</p><p>Record resource delta, clock estimates and the exact code change. Repeat a few route seeds to see placement variation. Keep each seed's raw report, including failures.</p><p>A feature-disabled core cannot run a DOT4 binary, so use an appropriate scalar program for workload comparison. Check the same mathematical outputs. Include scalar software multiplication under RV32I.</p><p>Convert cycles to estimated runtime using each configuration's own clock estimate. Report what is measured and what is inferred. The reference ablation finds DOT4 costs ${metrics.speedup.logicCellCost}% more logic cells and ${metrics.speedup.fmaxCost}% of median Fmax.</p><p>Keep negative results. If DOT4 saves cycles but lowers clock enough to erase the gain, that is an informative architecture result.</p>`),
 P('Step 6: adapt to synchronous FPGA memory',`<p>The reference expects combinational instruction/data reads. Typical FPGA block RAM returns data after a clocked read. Treat that as an interface change, not a wiring substitution. The reference board image sidesteps it by clocking block RAM on the falling edge, which halves the memory path budget (<code>docs/BOARD.md</code>).</p><p>For a first adaptation, choose either a fixed synchronous-read pipeline contract or a request/response protocol. Specify when a request is accepted and which saved instruction receives the response.</p><p>Preserve load address, size, destination and instruction identity until the response arrives. Extend the interlock so dependent work waits. Prevent repeated stores if a stage is held. Squash or discard responses associated with canceled younger requests.</p><p>Instruction fetch also needs response alignment: store the requested PC with the returned instruction, and discard a stale sequential response after a redirect.</p><p>Start by simulating a one-cycle memory wrapper. Then vary the response delay if your protocol supports it. Do not quote the old one-bubble rule or old timing numbers after this architectural change without rerunning the corresponding checks.</p>`),
 P('Step 7: make a board demonstration observable',`<p>Before buying or selecting a board, verify current availability, supported toolchain, FPGA capacity, package, oscillator, programmer and documentation. The existing HX8K shell uses much of the available logic; a smaller device may not fit.</p><p>A real top needs board pin assignments, a known clock, reset synchronization/treatment, memory/program loading and a visible result. A small ROM program can compute a signature and display pass/fail on an LED or send it over UART.</p><p>Simulate the complete board top and memory wrapper before programming. Check clock constraints and I/O timing for the actual board. Preserve the program, expected signature, configured clock and observed output.</p><p>Only after a checked program runs at the configured physical clock can you describe it as “running at X MHz.” A board photograph without program/output evidence is insufficient.</p><p>The reference has such a top: <code>make board</code> builds an HX8K Breakout image whose self-test passes in simulation, ${metrics.board.fmax} MHz post-route. It has not run on a board.</p>`),
 answers(`<p><b>7A.</b> They include different hardware boundaries. Keep the same shell and only vary the feature under investigation.</p><p><b>7B.</b> No. Synthesis provides mapping evidence. Route supplies constrained timing estimates, and a physical board demonstration supplies observed operation at a configured clock.</p><h3>Completion check</h3><p>Reproduce the route, explain its limiting path and resource units, and state excluded hardware. For board work, finish the new memory contract and full-top simulation before making operating-frequency claims.</p>`)
 ]},
{
 id:'08-research-release',number:8,title:'RESEARCH AND RELEASE',subtitle:'Turn code and experiments into an artifact someone can trust',summary:'Organize hypotheses, preserve evidence, reproduce reports, publish a clear repository and prepare a technical explanation.',sources:['repo','act4','formal'],
 pages:[road('You will keep a research trail across every build stage and publish a reproducible, accurately scoped project. The output is an evidence-backed repository and a demonstration you can explain.','docs/EXPERIMENT_LOG.md, docs/RESEARCH.md, README.md, reports/, .github/workflows/verify.yml and your learning branch.','Use the earlier volumes for implementation. Do not assume a metric or experiment is complete because it appears in a plan.', ['Write questions before editing.','Preserve exact code, inputs and commands.','Compare one variable at a time.','Reproduce in a clean environment.','Publish the complete evidence boundary.','Prepare a specific technical discussion.']),
 P('Step 1: start with a question you can test',`<p>A research question names a behavior or tradeoff and a comparison. “Is the core good?” is too broad. “Does this forwarding priority select the newest result?” has a direct counterexample test.</p><p>Write a hypothesis and an observation that would contradict it. Then select the smallest program or implementation run that could expose the difference.</p><p>For the pipeline, ask whether every dependent consumer sees the right producer. For DOT4, ask whether cycle savings survive clock/area costs. For verification, ask which bug could survive the current bin plan.</p><p>Use primary ISA/tool sources to establish definitions, and local experiments to establish this implementation's behavior. Do not cite a lab's research page as evidence that your own design is correct.</p><p>The project began from a placeholder README and an assistant-generated reference, with no earlier core draft. Preserve that provenance while recording the work you personally perform.</p>`,{exercise:'8A. Turn “DOT4 is faster” into a falsifiable question with an explicit baseline and workload.'}),
 P('Step 2: spread research across the build',`<dl class="glossary"><dt>Foundations</dt><dd>Predict old/new values across an edge and test the prediction.</dd><dt>Datapath</dt><dd>Derive encodings and signed behavior from the ISA, then test edge cases.</dd><dt>Pipeline</dt><dd>Predict each stage's instruction identity and compare the trace.</dd><dt>Hazards</dt><dd>Disable one mechanism in an isolated experiment and identify its first failure.</dd><dt>DOT4</dt><dd>Compare exact signed-lane math and later a matched scalar kernel.</dd><dt>Verification</dt><dd>Ask which behavior the current coverage plan does not exercise.</dd><dt>Implementation</dt><dd>Identify the critical path and compare one controlled configuration change.</dd><dt>Release</dt><dd>Have a clean clone reproduce the documented claims.</dd></dl><p>Reading belongs immediately before the decision it informs. Preserve failed predictions as well as successful results.</p>`),
 P('Step 3: make a complete experiment entry',`<p>Use the template already in docs/EXPERIMENT_LOG.md. A useful entry lets another person repeat the observation.</p>${code('Question and primary source:\nPrediction and possible falsifier:\nGit revision and RTL hashes:\nTool versions, target and seed:\nExact command and input program:\nExpected result:\nObserved result and raw artifact path:\nLimitation, decision and next experiment:')}<p>Record the program words, not only a screenshot. Record the source revision with a seed. Record frequency constraint and target with an Fmax estimate. Keep source changes and report files together.</p><p>Do not replace the observation with a conclusion such as “works perfectly.” State what the test checked, what it observed and what remains outside its scope.</p><p>For a deliberate defect experiment, preserve the patch separately from the working branch. Explain why restoring the intended mechanism resolves that particular counterexample.</p>`),
 P('Step 4: control the comparison',`<p>Change one meaningful variable at a time. A DOT4 experiment should not simultaneously change memory size, target device, software workload and synthesis top.</p><p>Keep the original input and expected output fixed. Record any overhead included or excluded. For a scalar-versus-packed kernel, packing and memory traffic can matter as much as the arithmetic.</p><p>A repeated seed is useful only with the same relevant tool/source inputs. New versions may alter mapping, route quality or coverage instrumentation. Preserve tool identities and raw results.</p><p>State an inference explicitly. “The path report suggests forwarding selection limits timing” is different from a measured causal improvement after simplifying that path.</p><p>Use several route seeds to assess placement sensitivity when making comparative claims. Do not report only the best favorable run while hiding failures or worse results.</p>`,{exercise:'8B. Why does comparing different synthesis tops weaken an area claim even if both reports mention the same core?'}),
 P('Step 5: reproduce from a clean clone',`<p>Use a separate directory so generated local files cannot silently supply missing dependencies. The public repository is already available; use its actual URL.</p>${code('git clone https://github.com/RahilBhavan/riscv.git riscv-check\ncd riscv-check\ndocker build -t rv32-tools .\ndocker run --rm --user "$(id -u):$(id -g)" \\\n  -v "$PWD:/work" rv32-tools \\\n  make test lint coverage timing')}<p>Compare tool versions, RTL hashes and summary results. Raw logs can differ in runtime bookkeeping even when the important measurements reproduce.</p><p>The Dockerfile uses distribution packages rather than permanently pinned binary versions. For a lasting publication, archive the built image digest or an equivalent precise environment alongside the source.</p><p>Rebuilding these textbooks is separate: <code>make textbook-series</code> uses Node and Chromium on the host. The hardware-tools image does not promise the document renderer.</p>`),
 P('Step 6: write a README around reproducible claims',`<p>Lead with the implemented behavior and one command that runs it. Link architecture assumptions, source, verification and implementation reports beside the relevant claims.</p><p>For coverage, name the metric and numerator/denominator. For resources, name the device and boundary. For timing, distinguish requested constraint, achieved estimate and physical operation.</p><p>For this reference, the current figures are ${metrics.regression.programs} passing programs, ${metrics.regression.retired} checked retirement records, ${metrics.coverage.hit}/${metrics.coverage.total} core line instrumentation points and a ${metrics.fmax.median} MHz median post-route estimate. These are not automatically your edited version's figures.</p><p>Keep limitations visible: combinational memory, local halt/trap behavior, no certification or formal integration, no physical board test, and a speedup measured on one kernel.</p><p>Do not write “95% test coverage, running at X MHz” when you measured a narrow line metric and a route estimate. The more precise description is more useful to a technical reader.</p>`),
 P('Step 7: publish the learning work',`<p>The repository already has a GitHub remote. Inspect it before pushing, then publish your learning branch with a descriptive commit.</p>${code('git status --short\ngit diff --check\ngit remote -v\ngit add rtl tests docs reports\ngit commit -m "Explain the specific implemented change"\ngit push -u origin learning/build-core')}<p>Stage only files belonging to the intended change. Review generated reports and source hashes before committing. Do not add build caches, credentials or unrelated local notes.</p><p>The existing GitHub Actions workflow runs differential tests, lint, coverage and route, then uploads reports/logs. Inspect the run and artifacts after pushing. A remote repository with a stale README does not establish current results.</p><p>A pull request can make your changes reviewable before merging into main. Write the problem, resulting behavior and relevant validation for someone who has not seen this conversation.</p>`),
 P('Step 8: prepare a technical explanation',`<p>Use a short demonstration with a concrete program and checked outputs. Explain why a consumer needs forwarding, why a load creates a bubble, and how an EX redirect prevents a wrong-path store.</p><p>Calculate one mixed-sign DOT4 result by hand, then show the simulator's matching record. Explain which instruction fields select the custom operation and how the result enters ordinary forwarding.</p><p>Show a coverage report and its small denominator. Show the critical path and the hardware excluded from the implementation boundary. State one next experiment that could change your conclusion.</p><p>Distinguish the assistant-generated reference, the changes you wrote, the experiments you ran and the behavior you can explain. Your contribution can be specific and valuable without claiming every line as independent original work.</p><p>Practice answering a question by pointing to code or a trace, rather than repeating a headline metric.</p>`),
 P('Step 9: connect the artifact to research interests',`<p>Verify each recipient's full name and current interests before personalizing outreach. The qualified Michigan matches and primary profile links are in docs/RESEARCH.md.</p><p>For Das and Dreslinski, explain an introductory compute/architecture tradeoff and its measured limits. A four-byte dot unit is not in-memory computing, near-threshold silicon or a reproduction of either lab's accelerator work.</p><p>For Austin, a reproducible hazard counterexample and verification method are a more direct artifact. For Shahbaz and Chowdhury, reproducibility and systems evaluation are transferable skills, while a small core is an indirect research fit.</p><p>Link one public artifact and one specific observation. Do not claim a faculty member requested the design, that a lab endorsed it, or that a planned experiment already succeeded.</p><p>This volume prepares the evidence and explanation. It does not send emails or publish statements on your behalf.</p>`),
 answers(`<p><b>8A.</b> Example: on the same packed signed-byte inputs and checked outputs, does a DOT4 kernel reduce total cycles relative to a scalar RV32I software-multiply kernel after including packing and loop overhead? Then compare estimated runtime using each configuration's own route result.</p><p><b>8B.</b> Different tops include different hardware, so the measured resource difference cannot be attributed solely to the feature.</p><h3>Completion check</h3><p>A clean clone reproduces the commands. Every headline has a linked report and scope. Your notes separate predictions, observations and unperformed work. You can explain one failure, fix and next test.</p>`)
 ]}
];
